  const observer = { acquisition: async () => { if (missingAcquisition) throw Error('missing source');return {}; }, checkpoint: async () => ({ requests: [] }), raw: async () => [] };
  return { progress, original, current: () => settings, cleanup: () => cleanup, run: () => verifyStandaloneWhole(page, progress, { kind: 'commit', observer, poll: async (fn, accept) => { const value = await fn();if (!accept(value)) throw Error('Probe timeout');return value; }, capture: async () => ({}), readSettings: async () => structuredClone(settings), writeSettings: async (value) => { settings = structuredClone(value); }, readState: async () => counts() }) };
